CREATE TABLE refunds (id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,order_id VARCHAR(64) NOT NULL,payment_id VARCHAR(64) NOT NULL,amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency CHAR(3) NOT NULL,type VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,reason VARCHAR(500) NOT NULL,provider_refund_id VARCHAR(160),idempotency_key VARCHAR(160) NOT NULL,request_hash CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,UNIQUE(user_id,idempotency_key));
CREATE TABLE refund_items(refund_id VARCHAR(64) REFERENCES refunds(id) ON DELETE CASCADE,variant_id VARCHAR(64) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),amount_minor BIGINT NOT NULL,PRIMARY KEY(refund_id,variant_id));
CREATE TABLE refund_status_history(id VARCHAR(64) PRIMARY KEY,refund_id VARCHAR(64) NOT NULL REFERENCES refunds(id),from_status VARCHAR(32),to_status VARCHAR(32) NOT NULL,actor_id VARCHAR(64) NOT NULL,reason VARCHAR(500),created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE refund_reconciliation(id VARCHAR(64) PRIMARY KEY,refund_id VARCHAR(64) NOT NULL REFERENCES refunds(id),outcome VARCHAR(32) NOT NULL,checked_at TIMESTAMPTZ NOT NULL);
CREATE TABLE refund_inbox_events(event_id VARCHAR(160) PRIMARY KEY,received_at TIMESTAMPTZ NOT NULL);
CREATE TABLE refund_outbox_events(id VARCHAR(64) PRIMARY KEY,aggregate_id VARCHAR(64) NOT NULL,event_type VARCHAR(100) NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,occurred_at TIMESTAMPTZ NOT NULL,correlation_id VARCHAR(160) NOT NULL,payload_json JSONB NOT NULL,published_at TIMESTAMPTZ);
CREATE INDEX refund_outbox_unpublished_idx ON refund_outbox_events(published_at,occurred_at) WHERE published_at IS NULL;
